import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1787063576000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>mcp-hub is exposed to the internet by design, so its security properties are part of its interface. This page describes the trust model, the controls that exist, and the deployment choices that are your responsibility.</p><p>The canonical policy lives in <a href="https://github.com/ni-c/mcp-hub/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> in the repository.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Use <a href="https://github.com/ni-c/mcp-hub/security/advisories/new" target="_blank" rel="noreferrer">GitHub private vulnerability reporting</a>. Please do not open a public issue for an unpatched vulnerability, and do not include real credentials, tokens, hostnames or private configuration in a report.</p><p>Only the latest release and the current <code>main</code> branch receive security fixes.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust model”">​</a></h2><p><strong>mcp-hub is an authorization gateway, not a sandbox.</strong></p><p>Every stdio server configured in the hub container runs as the same operating-system user as the hub itself. It can therefore read the hub&#39;s mounted files — including <code>/data/jwt-key.pem</code> and <code>/data/state.json</code> — inspect the hub process, and reach whatever the container&#39;s network policy allows.</p><p>The consequences are worth stating plainly:</p><ul><li>A malicious or compromised stdio package in your <code>mcp.json</code> can mint its own access tokens and reach every other server in the hub.</li><li>Only run stdio packages you have reviewed and trust.</li><li>Servers with a different trust level belong in <strong>separate containers or hosts</strong>, with their own filesystem, credentials and network policy.</li></ul><p>For those, <a href="/guide/sandboxing">sandboxing</a> is the direct route: <code>type: &quot;docker&quot;</code> has the hub create the container and speak stdio to it over the Docker API, <code>type: &quot;unix&quot;</code> connects to a container you started yourself. Both keep the protocol on a byte stream, so the sandboxed server needs no HTTP listener, no bearer token and no bridge process in its image — and with a Unix socket it can run with <code>network_mode: none</code>, which an HTTP upstream can never do. Connecting a server that already speaks HTTP as a <a href="/guide/configuration#remote-servers">remote upstream</a> remains equally valid; it has no access to the hub&#39;s process or files either.</p><p><strong>The hub never gets the Docker socket.</strong> <code>type: &quot;docker&quot;</code> is served by a separate <code>mcp-hub-docker-proxy</code> container, which holds the daemon socket and allows only the container operations <code>mcp.json</code> describes — no privileged containers, no host mounts, no foreign images, whatever the hub asks for. The daemon API is root-equivalent, and the hub is the part exposed to the internet; those two must not meet. See <a href="/guide/sandboxing#the-policy-proxy">the policy proxy</a>.</p><p>A sandboxed server&#39;s credentials can be kept out of the hub entirely with <code>secretsFrom</code>: the proxy holds the env file and adds the variables after it has validated the request, so they never enter the process whose children can read <code>/proc/1/environ</code>.</p><p>Avoid <code>npx -y</code>, unversioned <code>uvx</code>, mutable Git branches and any other runtime download. Install reviewed, exactly-versioned server packages while building a <a href="/guide/deployment#custom-image">custom image</a>, scan that image, and keep the runtime root filesystem read-only.</p><h2 id="deployment-checklist" tabindex="-1">Deployment checklist <a class="header-anchor" href="#deployment-checklist" aria-label="Permalink to “Deployment checklist”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> TLS terminated at a trusted reverse proxy; <code>EXTERNAL_URL</code> set to the exact public HTTPS origin</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"><code>TRUSTED_PROXIES</code> set to proxy addresses that <strong>overwrite</strong> forwarded headers (<a href="#trusted-proxies">details below</a>)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"><code>PASSWORD_HASH</code> rather than a plain-text <code>PASSWORD</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"><code>/data</code> on a persistent, private volume</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"><code>RESOURCE_BOUND_TOKENS</code> left at its default (<code>true</code>) — the migration mode is not still switched off</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> The example&#39;s non-root user, dropped capabilities, read-only root filesystem, <code>pids_limit</code>, memory limit and <code>no-new-privileges</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"><code>/data/jwt-key.pem</code>, <code>/data/state.json</code>, the MCP config and every referenced environment variable treated as secrets</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> Outbound network access restricted to what the configured servers need</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" disabled="disabled"><label class="task-list-item-label" for="task-item-8"><code>/var/run/docker.sock</code> mounted <strong>only</strong> into <code>mcp-hub-docker-proxy</code>, never into the hub, and both images on the same version</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" disabled="disabled"><label class="task-list-item-label" for="task-item-9"> Sandbox secret files (<code>secretsFrom</code>) <code>chmod 640</code> and mounted into the proxy only</label></li></ul><h2 id="authentication-and-authorization" tabindex="-1">Authentication and authorization <a class="header-anchor" href="#authentication-and-authorization" aria-label="Permalink to “Authentication and authorization”">​</a></h2><p><strong>One password.</strong> There are no user accounts. Anyone who knows the password can approve a client and reach every server the hub exposes. Use a strong one and store the bcrypt hash, not the plain text.</p><p><strong>Registration is open, approval is not.</strong> Dynamic client registration is unauthenticated, as the MCP specification intends. Registering grants nothing — a client receives an authorization code only after you confirmed it, and only at the redirect URI you confirmed. Never-approved registrations are pruned at a fixed cap of 100, so an open endpoint cannot grow the state file without bound; approved clients are never pruned.</p><p><strong>Consent is explicit.</strong> Entering the password approves the client that asked for it. While a login session is still valid, a client the hub has not seen before gets a CSRF-protected <em>Approve / Deny</em> page rather than a silent code. This is what stops a page in another tab from riding your session to obtain a token.</p><p><strong>Tokens are short-lived and bound.</strong> Access tokens are EdDSA-signed JWTs valid for 15 minutes; the verifier pins the algorithm rather than trusting the token header. Refresh tokens rotate, reuse of a retired token revokes its family, and a refresh cannot request more scope than the original grant. Each token is additionally bound (RFC 8707) to the one resource it was issued for, so a token for one server reaches neither another server nor <code>/hub</code> and <code>/health</code>.</p><p><strong>Revocation takes effect at once.</strong> <code>mcp-hub-admin clients revoke &lt;id&gt;</code> removes the approval and every refresh token, and sets a marker that rejects already-issued access tokens immediately — no waiting for the 15-minute expiry. It works whether or not the hub is running: the CLI is a second process on the same state file, and both sides re-read it before touching it, so neither can serve a stale copy or write one back over the other.</p><p><strong>API tokens are the deliberate exception.</strong> <code>mcp-hub-admin tokens create</code> mints long-lived tokens for <a href="/guide/client-compatibility#camp-2-api-clients-use-an-api-token">clients that cannot do OAuth</a> — no refresh, no rotation, one resource. The mitigations are procedural: short lifetimes, one token per integration, immediate revocation via <code>tokens revoke</code> (verification refuses a revoked token even though its signature still checks out). A leaked API token is equivalent to a leaked password scoped to one resource.</p><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to “Rate limits”">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Per IP</th><th>Global</th></tr></thead><tbody><tr><td><code>/register</code></td><td>20 per hour</td><td>200 per hour</td></tr><tr><td><code>/authorize</code></td><td>100 per 15 min</td><td>1000 per 15 min</td></tr><tr><td><code>/token</code></td><td>50 per 15 min</td><td>500 per 15 min</td></tr><tr><td><code>/login</code></td><td>100 per 15 min</td><td>500 per 15 min</td></tr><tr><td><code>/consent</code></td><td>100 per 15 min</td><td>500 per 15 min</td></tr><tr><td>Failed logins</td><td>10 per 15 min</td><td>100 per 15 min</td></tr><tr><td>MCP traffic</td><td><code>MCP_REQUESTS_PER_MINUTE</code> (120) and <code>MCP_MAX_CONCURRENT_REQUESTS</code> (4) <strong>per OAuth client</strong></td><td>—</td></tr></tbody></table><p>The auth limiters run <strong>before</strong> body parsing, and they reject without inserting the offending IP into their tables, so a flood of forged addresses cannot grow memory. The global counters exist precisely because an attacker who rotates <code>X-Forwarded-For</code> would otherwise dodge the per-IP limit.</p><p>MCP traffic is limited per OAuth client rather than per IP: behind a reverse proxy every client shares one source address, so an IP key would let one connector starve the others.</p><p>Failed logins are written to the log as:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>mcp-hub: authentication failure from &lt;ip&gt;</span></span></code></pre></div><p>which is what the <a href="/guide/deployment#fail2ban">fail2ban integration</a> matches on.</p><h2 id="trusted-proxies" tabindex="-1">Trusted proxies <a class="header-anchor" href="#trusted-proxies" aria-label="Permalink to “Trusted proxies”">​</a></h2><p><code>TRUSTED_PROXIES</code> is a comma-separated list of IPs or CIDRs allowed to set <code>X-Forwarded-*</code>. It decides what <code>req.ip</code> is, and therefore what the login rate limiter counts.</p><div class="danger custom-block"><p class="custom-block-title">Two ways to get this wrong</p><p><strong>Too permissive:</strong> if a client&#39;s own <code>X-Forwarded-For</code> is believed, it can supply an address, rotate it, and sidestep the per-IP limit entirely.</p><p><strong>Unset:</strong> every request appears to come from the proxy, so per-IP limiting collapses into a single global counter. The hub logs a warning at startup when this happens.</p></div><p>List only your own reverse proxy, and make sure that proxy <em>overwrites</em><code>X-Forwarded-For</code> instead of appending to it. In nginx that means <code>proxy_set_header X-Forwarded-For $remote_addr;</code> — not the <code>$proxy_add_…</code> variant, which preserves whatever the client sent.</p><p>The global cap of 100 failed logins per 15 minutes applies regardless, as a backstop.</p><h2 id="browser-facing-hardening" tabindex="-1">Browser-facing hardening <a class="header-anchor" href="#browser-facing-hardening" aria-label="Permalink to “Browser-facing hardening”">​</a></h2><p>The login and consent pages deny framing and carry a restrictive Content-Security-Policy. Auth responses are <code>Cache-Control: no-store</code>. The session cookie is <code>HttpOnly</code>, <code>SameSite=Lax</code> and carries the <code>__Host-</code> prefix when <code>EXTERNAL_URL</code> is HTTPS.</p><p>MCP request bodies are parsed only <em>after</em> the bearer token has been verified, and are then bounded by <code>MCP_BODY_LIMIT</code>, the per-client request rate and the per-client concurrency limit.</p><p>Child responses are bounded too: forwarded results stop at 8 MiB, tool discovery at 100 pages, 10,000 tools and 16 MiB of metadata. Tool calls have a five-minute deadline, and it is absolute by default — progress notifications do not extend it, because a child that emits one every few seconds could otherwise hold a request, and one of the client&#39;s concurrency slots, open forever. A deployment with genuinely long-running tools can raise <code>MCP_CALL_TIMEOUT_MS</code> or set <code>MCP_RESET_TIMEOUT_ON_PROGRESS=true</code>; both trade that bound for convenience and need <code>HTTP_REQUEST_TIMEOUT_MS</code> and the reverse proxy raised to match. A sandbox that sends an oversized or corrupt Docker frame has its stream closed, container cleaned up and restart delayed by the normal supervisor backoff.</p><h2 id="what-the-hub-does-not-protect-against" tabindex="-1">What the hub does not protect against <a class="header-anchor" href="#what-the-hub-does-not-protect-against" aria-label="Permalink to “What the hub does not protect against”">​</a></h2><ul><li><strong>A compromised stdio server.</strong> See the trust model — this is the big one.</li><li><strong>Password compromise.</strong> One password, full access. There is no second factor.</li><li><strong>A malicious reverse proxy.</strong> The hub trusts it for TLS and client addresses.</li><li><strong>Denial of service at the network layer.</strong> Rate limits protect the process, not your bandwidth.</li><li><strong>Data exfiltration by an authorized client.</strong> Once approved, a client can call every tool its token covers.</li></ul><h2 id="supply-chain" tabindex="-1">Supply chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to “Supply chain”">​</a></h2><p>Base images and GitHub Actions are pinned by digest or commit SHA. Every push is gated by CodeQL, a required Trivy secret scan and Trivy image scans (<code>HIGH</code>/<code>CRITICAL</code>, failing the build) before an image is published; images carry an SBOM and <code>mode=max</code> provenance. npm releases are published through Trusted Publishing (OIDC) with provenance attestation. The registry publisher is version- and checksum-pinned. Release tags must match <code>package.json</code> and point to a commit reachable from <code>main</code>. Dependabot tracks npm, Docker and Actions dependencies weekly; only patch updates to direct development dependencies are eligible for automatic merge.</p><p>The runtime image replaces the bundled npm with a current version and patches the two vendored packages that still ship known-vulnerable releases, so a scan of the published image reports no fixable HIGH or CRITICAL findings.</p>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};